from app.api.v1.auth import register, login, normalize_email
from app.schemas.user import UserCreate

class FakeCollection:
    def __init__(self):
        self.docs = []
    def insert_one(self, doc):
        self.docs.append(doc)
    def find_one(self, query):
        if isinstance(query, dict) and 'email' in query and not isinstance(query['email'], dict):
            for doc in self.docs:
                if doc.get('email') == query['email']:
                    return doc
            return None
        return None
    def find(self, query):
        return [d for d in self.docs if 'email' in d]

class FakeDB:
    def __init__(self):
        self.users = FakeCollection()

